"""Golden archive is generated by the original Deck v1.4.5 pack_current."""
import json
from pathlib import Path

from umeyc_steamback.engine import Config, Engine
from umeyc_steamback.protocol.cloud import pack_current, unpack_verified

FIXTURES = Path(__file__).parent / "fixtures"


def test_deck_archive_readable_and_windows_content_hash_matches(tmp_path):
    golden = json.loads((FIXTURES / "deck-custom-v1.json").read_text(encoding="utf-8"))
    game = {"game_id": 42, "game_name": "Compatibility", "install_root": str(tmp_path / "Steam")}
    staging = tmp_path / "decoded"
    manifest = unpack_verified(FIXTURES / "deck-custom-v1.zip", staging, game, 123, golden["content_hash"])
    assert manifest == golden
    assert (staging / "0/profile/中文.sav").read_bytes() == b"chapter 3\n"
    engine = Engine(Config(str(tmp_path / "data"), str(tmp_path / "Steam")))
    engine.account_ids = {123}
    engine.configure(game, [str(staging / "0")])
    repacked = pack_current(engine, game, tmp_path / "windows.zip")
    assert repacked == golden
